import crypto from 'node:crypto';
import express from 'express';
import session from 'express-session';
import { rateLimit } from 'express-rate-limit';
import argon2 from 'argon2';

const PORT = process.env.PORT ?? 3000;
const PROD = process.env.NODE_ENV === 'production';

const SESSION_SECRET = process.env.SESSION_SECRET;
if (!SESSION_SECRET && PROD) {
  throw new Error('SESSION_SECRET must be set in production');
}

const WINDOW_MS = 15 * 60 * 1000;
const MAX_FAILURES_PER_IP = 20;
const MAX_FAILURES_PER_ACCOUNT = 5;
const MAX_PASSWORD_LENGTH = 1024;

// Swap for a real database. Keyed by lowercased username.
const users = new Map();

// Verified against when the username doesn't exist, so that unknown users
// take as long to reject as known ones.
const DUMMY_HASH = await argon2.hash(crypto.randomBytes(16));

const app = express();

// Behind a reverse proxy, set this so req.ip and secure cookies work:
// app.set('trust proxy', 1);

app.use(express.json({ limit: '10kb' }));

app.use(
  session({
    name: 'sid',
    secret: SESSION_SECRET ?? crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    // The default MemoryStore leaks and is per-process; use a Redis/SQL store in production.
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: PROD,
      maxAge: 24 * 60 * 60 * 1000,
    },
  }),
);

// Both limiters count only failed attempts: successful (<400) responses are refunded.
const limiterOptions = {
  windowMs: WINDOW_MS,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-8',
  legacyHeaders: false,
  message: { error: 'Too many failed attempts. Try again later.' },
};

const ipLimiter = rateLimit({
  ...limiterOptions,
  limit: MAX_FAILURES_PER_IP,
});

const accountLimiter = rateLimit({
  ...limiterOptions,
  limit: MAX_FAILURES_PER_ACCOUNT,
  keyGenerator: (req) => req.body.username.toLowerCase(),
});

function validateCredentials(req, res, next) {
  const { username, password } = req.body ?? {};
  if (
    typeof username !== 'string' ||
    typeof password !== 'string' ||
    !username ||
    !password ||
    username.length > 64 ||
    password.length > MAX_PASSWORD_LENGTH
  ) {
    return res.status(400).json({ error: 'Invalid username or password format.' });
  }
  next();
}

function requireAuth(req, res, next) {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Not authenticated.' });
  }
  next();
}

app.post('/register', ipLimiter, validateCredentials, async (req, res) => {
  const { username, password } = req.body;
  const key = username.toLowerCase();

  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters.' });
  }
  if (users.has(key)) {
    return res.status(409).json({ error: 'Username is taken.' });
  }

  // argon2id with a per-password random salt, encoded into the hash string.
  const passwordHash = await argon2.hash(password);
  users.set(key, { id: crypto.randomUUID(), username, passwordHash });
  res.status(201).json({ username });
});

app.post('/login', ipLimiter, validateCredentials, accountLimiter, async (req, res, next) => {
  const { username, password } = req.body;
  const user = users.get(username.toLowerCase());

  const ok = await argon2.verify(user?.passwordHash ?? DUMMY_HASH, password);
  if (!user || !ok) {
    // Same response for unknown user and wrong password.
    return res.status(401).json({ error: 'Invalid username or password.' });
  }

  // New session id on privilege change, to prevent session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    req.session.username = user.username;
    res.json({ username: user.username });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.status(204).end();
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error.' });
});

app.listen(PORT, () => {
  console.log(`Listening on http://localhost:${PORT}`);
});

